  switch ($lang) {
    case 'en': return '🇺🇸';
    case 'tr': return '🇹🇷';
    case 'es': return '🇪🇸';
    case 'pt': return '🇵🇹';
    case 'fr': return '🇫🇷';
    case 'de': return '🇩🇪';
    case 'it': return '🇮🇹';
    case 'ru': return '🇷🇺';
    case 'ar': return '🇸🇦';
    case 'fa': return '🇮🇷';
    case 'hi': return '🇮🇳';
    case 'bn': return '🇧🇩';
    case 'id': return '🇮🇩';
    case 'vi': return '🇻🇳';
    case 'ja': return '🇯🇵';
    case 'ko': return '🇰🇷';
    case 'zh-CN': return '🇨🇳';
    case 'yue': return '🇭🇰';
    case 'wuu': return '🇨🇳';
    default: return '🌐';
  }
}

function lang_flag_img($lang) {
  $map = [
    'en' => 'flags/United-kingdom.png',
    'tr' => 'flags/Turkey.png',
    'zh-CN' => 'flags/China.png',
    'es' => 'flags/Spain.png',
